/** The contents of tokens.css, for documents that inline the design tokens. */
export const TOKENS_CSS =
  '/*\n * Portifact design tokens. The palette is monochromatic: a single neutral ramp with zero\n * saturation (see docs/design.md, "Palette"). Apps use the semantic tokens only.\n */\n\n:root {\n  /* Primitive neutral ramp, white to black. */\n  --pf-neutral-0: #ffffff;\n  --pf-neutral-50: #f7f7f7;\n  --pf-neutral-100: #efefef;\n  --pf-neutral-150: #e5e5e5;\n  --pf-neutral-200: #dedede;\n  --pf-neutral-300: #c4c4c4;\n  --pf-neutral-400: #9e9e9e;\n  --pf-neutral-500: #767676;\n  --pf-neutral-600: #5c5c5c;\n  --pf-neutral-700: #3a3a3a;\n  --pf-neutral-800: #262626;\n  --pf-neutral-850: #1c1c1c;\n  --pf-neutral-900: #141414;\n  --pf-neutral-950: #0f0f0f;\n  --pf-neutral-1000: #000000;\n\n  /* Typography */\n  --pf-font-sans:\n    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;\n  --pf-font-mono:\n    ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;\n\n  /* Type scale and rhythm, for surfaces styled without Tailwind such as the document viewers. */\n  --pf-text-sm: 0.875rem;\n  --pf-text-base: 1rem;\n  --pf-text-lg: 1.125rem;\n  --pf-text-xl: 1.25rem;\n  --pf-text-2xl: 1.5rem;\n  --pf-text-3xl: 2rem;\n  --pf-leading-tight: 1.25;\n  --pf-leading-normal: 1.6;\n  --pf-weight-normal: 400;\n  --pf-weight-semibold: 600;\n  --pf-weight-bold: 700;\n\n  /* Spacing scale and layout */\n  --pf-space-1: 0.25rem;\n  --pf-space-2: 0.5rem;\n  --pf-space-3: 0.75rem;\n  --pf-space-4: 1rem;\n  --pf-space-6: 1.5rem;\n  --pf-space-8: 2rem;\n  --pf-space-12: 3rem;\n  --pf-measure: 72ch;\n  --pf-border-width: 1px;\n  --pf-border-width-strong: 3px;\n\n  /* Radii and motion */\n  --pf-radius-xs: 3px;\n  --pf-radius-sm: 6px;\n  --pf-radius-md: 10px;\n  --pf-radius-lg: 16px;\n  --pf-duration-fast: 120ms;\n  --pf-duration-base: 240ms;\n  --pf-duration-slow: 700ms;\n  --pf-duration-stagger: 200ms;\n  --pf-ease-out: cubic-bezier(0.16, 1, 0.3, 1);\n\n  /* Elevation. Shadows are pure black at low alpha, so they stay neutral in both themes. */\n  --pf-shadow-sm: 0 1px 2px rgb(0 0 0 / 0.06);\n  --pf-shadow-float: 0 1px 2px rgb(0 0 0 / 0.06), 0 24px 64px -24px rgb(0 0 0 / 0.28);\n}\n\n/* Light theme (default). */\n:root,\n[data-theme="light"] {\n  color-scheme: light;\n  --pf-color-canvas: var(--pf-neutral-0);\n  --pf-color-surface: var(--pf-neutral-50);\n  --pf-color-surface-raised: var(--pf-neutral-0);\n  --pf-color-surface-inverse: var(--pf-neutral-1000);\n  --pf-color-text: var(--pf-neutral-1000);\n  --pf-color-text-muted: var(--pf-neutral-600);\n  --pf-color-text-inverse: var(--pf-neutral-0);\n  --pf-color-border: var(--pf-neutral-150);\n  --pf-color-border-strong: var(--pf-neutral-500);\n  --pf-color-selection: var(--pf-neutral-200);\n  --pf-color-focus: var(--pf-neutral-1000);\n  --pf-color-danger: var(--pf-neutral-1000);\n  --pf-color-warning: var(--pf-neutral-1000);\n  --pf-color-success: var(--pf-neutral-1000);\n  --pf-color-info: var(--pf-neutral-1000);\n  --pf-color-terminal: var(--pf-neutral-900);\n  --pf-color-terminal-text: var(--pf-neutral-0);\n  --pf-color-terminal-muted: var(--pf-neutral-400);\n  --pf-color-terminal-border: var(--pf-neutral-800);\n}\n\n/* Dark theme: follows the system unless a theme is forced. */\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme="light"]) {\n    color-scheme: dark;\n    --pf-color-canvas: var(--pf-neutral-950);\n    --pf-color-surface: var(--pf-neutral-900);\n    --pf-color-surface-raised: var(--pf-neutral-850);\n    --pf-color-surface-inverse: var(--pf-neutral-0);\n    --pf-color-text: var(--pf-neutral-0);\n    --pf-color-text-muted: var(--pf-neutral-400);\n    --pf-color-text-inverse: var(--pf-neutral-1000);\n    --pf-color-border: var(--pf-neutral-800);\n    --pf-color-border-strong: var(--pf-neutral-500);\n    --pf-color-selection: var(--pf-neutral-700);\n    --pf-color-focus: var(--pf-neutral-0);\n    --pf-color-danger: var(--pf-neutral-0);\n    --pf-color-warning: var(--pf-neutral-0);\n    --pf-color-success: var(--pf-neutral-0);\n    --pf-color-info: var(--pf-neutral-0);\n    --pf-color-terminal: var(--pf-neutral-1000);\n    --pf-color-terminal-text: var(--pf-neutral-0);\n    --pf-color-terminal-muted: var(--pf-neutral-400);\n    --pf-color-terminal-border: var(--pf-neutral-800);\n  }\n}\n\n[data-theme="dark"] {\n  color-scheme: dark;\n  --pf-color-canvas: var(--pf-neutral-950);\n  --pf-color-surface: var(--pf-neutral-900);\n  --pf-color-surface-raised: var(--pf-neutral-850);\n  --pf-color-surface-inverse: var(--pf-neutral-0);\n  --pf-color-text: var(--pf-neutral-0);\n  --pf-color-text-muted: var(--pf-neutral-400);\n  --pf-color-text-inverse: var(--pf-neutral-1000);\n  --pf-color-border: var(--pf-neutral-800);\n  --pf-color-border-strong: var(--pf-neutral-500);\n  --pf-color-selection: var(--pf-neutral-700);\n  --pf-color-focus: var(--pf-neutral-0);\n  --pf-color-danger: var(--pf-neutral-0);\n  --pf-color-warning: var(--pf-neutral-0);\n  --pf-color-success: var(--pf-neutral-0);\n  --pf-color-info: var(--pf-neutral-0);\n  --pf-color-terminal: var(--pf-neutral-1000);\n  --pf-color-terminal-text: var(--pf-neutral-0);\n  --pf-color-terminal-muted: var(--pf-neutral-400);\n  --pf-color-terminal-border: var(--pf-neutral-800);\n}\n';
